import math

def is_good_number(m):
    # m = x^2 + y^2 with x != y, x, y > 0, gcd(x, y) > 1
    # x^2 < m, so x < sqrt(m)
    for x in range(2, int(math.sqrt(m)) + 1):
        y2 = m - x*x
        if y2 <= 0:
            continue
        y = int(math.sqrt(y2))
        if y*y == y2:
            if x != y and y > 0 and math.gcd(x, y) > 1:
                return True
    return False

good_numbers = []
for m in range(1, 1000):
    if is_good_number(m):
        good_numbers.append(m)

