import math

def get_good_set_min(x, y, iterations=50):
    X = {x, y}
    for _ in range(iterations):
        new_X = set(X)
        elements = list(X)
        for a in elements:
            for b in elements:
                # The condition is a^2 + iab + b^2 in X for all i.
                # This means a^2+b^2 in X, a^2+ab+b^2 in X, etc.
                # It also means ab in X? No, it doesn't mean that.
                # Let's re-check.
                # (a^2 + (i+1)ab + b^2) - (a^2 + iab + b^2) = ab.
                # But this difference is not necessarily in X.
                # Only the elements themselves are in X.
                for i in range(-2, 3):
                    new_X.add(a*a + i*a*b + b*b)
        if new_X == X:
            break
        X = new_X
        if len(X) > 20000:
            break
    return X

s = get_good_set_min(5, 11)
print(f"G(5, 11) contains 1: {1 in s}")
print(f"G(5, 11) size: {len(s)}")

